struct Layer {
    std::vector<std::vector<double>> weight;
    std::vector<double> bias;
};

struct Model {
    Layer input_layer;
    Layer hidden_layer;
    Layer output_layer;
};

double relu(double x) {
    return std::max(0.0, x);
}

std::vector<double> forward_layer(const std::vector<double>& input, const Layer& layer) {
    std::vector<double> output(layer.bias.size());

    for (size_t i = 0; i < layer.weight.size(); ++i) {
        for (size_t j = 0; j < input.size(); ++j) {
            output[i] += layer.weight[i][j] * input[j];
        }
        output[i] += layer.bias[i];
    }

    return output;
}

std::vector<double> apply_relu(const std::vector<double>& input) {
    std::vector<double> output(input.size());
    for (size_t i = 0; i < input.size(); ++i) {
        output[i] = relu(input[i]);
    }
    return output;
}

int predict(const std::vector<double>& input, const Model& model) {
    // Forward pass through input layer + ReLU
    auto hidden1 = forward_layer(input, model.input_layer);
    hidden1 = apply_relu(hidden1);

    // Forward pass through hidden layer + ReLU
    auto hidden2 = forward_layer(hidden1, model.hidden_layer);
    hidden2 = apply_relu(hidden2);

    // Forward pass through output layer
    auto output = forward_layer(hidden2, model.output_layer);

    // Find argmax
