    cJSON* weight = cJSON_GetObjectItem(input_layer, "weight");
    cJSON* bias = cJSON_GetObjectItem(input_layer, "bias");

    int weight_rows = cJSON_GetArraySize(weight);
    model.input_layer.weight.resize(weight_rows);

    for (int i = 0; i < weight_rows; ++i) {
