        int cols = cJSON_GetArraySize(row);
        model.input_layer.weight[i].resize(cols);

        for (int j = 0; j < cols; ++j) {
            model.input_layer.weight[i][j] = cJSON_GetArrayItem(row, j)->valuedouble;
        }
    }

    int bias_size = cJSON_GetArraySize(bias);
    model.input_layer.bias.resize(bias_size);
    for (int i = 0; i < bias_size; ++i) {
